create extension if not exists "pgcrypto";
create table if not exists contact_submissions (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), name text not null, email text not null, phone text, company text, budget text not null, service text not null, message text not null, status text not null default 'new' check(status in ('new','contacted','archived')));
create table if not exists newsletter (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), email text not null unique, active boolean not null default true);
create table if not exists project_inquiries (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), contact_id uuid references contact_submissions(id) on delete cascade, project_type text, target_launch date, details jsonb default '{}'::jsonb);
create table if not exists bookings (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), name text not null, email text not null, company text, date date not null, time text not null, timezone text not null, notes text, status text not null default 'confirmed', unique(date,time));
alter table contact_submissions enable row level security;alter table newsletter enable row level security;alter table project_inquiries enable row level security;alter table bookings enable row level security;
-- The service-role key used by server routes bypasses RLS. No public policies are created.
